Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l4-orchestral-argument",
  "level": "L4",
  "title": "Chamber argument without words",
  "purpose": "An orchestral miniature where two ideas interrupt, listen, and finally coexist without fully agreeing.",
  "duration_seconds": 88,
  "section_plan": [
    "idea A: 8 bars",
    "idea B: 8 bars",
    "argument: 12 bars",
    "listening: 8 bars",
    "coexistence: 8 bars"
  ],
  "style": [
    "contemporary chamber orchestra",
    "contrapuntal",
    "playable"
  ],
  "mood": [
    "assertive",
    "wounded",
    "attentive",
    "ambiguous"
  ],
  "must_include": [
    "distinct A and B motives",
    "register-separated counterpoint",
    "dynamics shape the argument",
    "coexistence combines rather than stacks motives"
  ],
  "must_avoid": [
    "block-chord tutti throughout",
    "impossible leaps",
    "constant doubled unison",
    "film-trailer ending"
  ],
  "instrument_roles": [
    "violin line",
    "viola response",
    "cello line",
    "double bass support",
    "woodwind color",
    "horn support",
    "light percussion"
  ],
  "delivery": [
    "44 bars",
    "7 to 9 tracks",
    "CC1 or CC11 phrasing on sustained parts"
  ],
  "score_focus": [
    "counterpoint",
    "playability",
    "orchestral roles",
    "formal argument"
  ],
  "mode_a": false
}

SKELETON:
{"title":"Chamber argument without words","tempo_map":[{"bar":1,"bpm":120}],"key_map":[{"bar":1,"key":"E minor"}],"sections":[{"id":"idea_a","name":"Idea A","start_bar":1,"bars":8},{"id":"idea_b","name":"Idea B","start_bar":9,"bars":8},{"id":"argument","name":"Argument","start_bar":17,"bars":12},{"id":"listening","name":"Listening","start_bar":29,"bars":8},{"id":"coexistence","name":"Coexistence","start_bar":37,"bars":8}],"track_plan":[{"id":"vln","name":"Violin Line","role":"melody","register":{"low":55,"high":96},"instrument_hint":"violin arco","section_jobs":[{"section_id":"idea_a","intent":"state A motive, angular, assertive","density":"medium"},{"section_id":"idea_b","intent":"answer with B motive, cantabile","density":"medium"},{"section_id":"argument","intent":"interrupt and fragment A and B alternately","density":"dense"},{"section_id":"listening","intent":"sustain long tones, sparse interjections","density":"sparse"},{"section_id":"coexistence","intent":"combine A and B in counterpoint, sharing line","density":"medium"}]},{"id":"vla","name":"Viola Response","role":"countermelody","register":{"low":48,"high":79},"instrument_hint":"viola arco","section_jobs":[{"section_id":"idea_a","intent":"counter to A, descending line","density":"medium"},{"section_id":"idea_b","intent":"double or harmonize B, muted","density":"sparse"},{"section_id":"argument","intent":"rhythmic retorts, short gestures","density":"dense"},{"section_id":"listening","intent":"echo violin, very sparse","density":"sparse"},{"section_id":"coexistence","intent":"inner voice blends both motives","density":"medium"}]},{"id":"vlc","name":"Cello Line","role":"bass/tenor","register":{"low":36,"high":67},"instrument_hint":"cello arco/pizz","section_jobs":[{"section_id":"idea_a","intent":"provide bass foundation, pizzicato","density":"sparse"},{"section_id":"idea_b","intent":"legato countermelody","density":"medium"},{"section_id":"argument","intent":"agitated ostinato, short notes","density":"dense"},{"section_id":"listening","intent":"warm held notes","density":"sparse"},{"section_id":"coexistence","intent":"support harmonic blend, occasional pizz","density":"medium"}]},{"id":"db","name":"Double Bass Support","role":"bass foundation","register":{"low":28,"high":48},"instrument_hint":"double bass pizz/arco","section_jobs":[{"section_id":"idea_a","intent":"minimal root/fifth on downbeats","density":"sparse"},{"section_id":"idea_b","intent":"sustained pedal","density":"sparse"},{"section_id":"argument","intent":"pizzicato interjections","density":"medium"},{"section_id":"listening","intent":"low drone, very sparse","density":"sparse"},{"section_id":"coexistence","intent":"ground bass, simple","density":"sparse"}]},{"id":"ww","name":"Woodwind Color","role":"texture/color","register":{"low":60,"high":93},"instrument_hint":"flute/alto flute","section_jobs":[{"section_id":"idea_a","intent":"flourish on A motive tail","density":"sparse"},{"section_id":"idea_b","intent":"soft countermelody","density":"medium"},{"section_id":"argument","intent":"sharp rhythmic interjections","density":"medium"},{"section_id":"listening","intent":"breathy sustained tone","density":"sparse"},{"section_id":"coexistence","intent":"overtones, light filigree","density":"sparse"}]},{"id":"hn","name":"Horn Support","role":"harmony/pad","register":{"low":43,"high":65},"instrument_hint":"horn in F","section_jobs":[{"section_id":"idea_a","intent":"held chord tones, swells","density":"sparse"},{"section_id":"idea_b","intent":"respond with warm horn call","density":"medium"},{"section_id":"argument","intent":"accent dissonances, crescendo","density":"medium"},{"section_id":"listening","intent":"soft sustained harmony","density":"sparse"},{"section_id":"coexistence","intent":"blend sustained chords","density":"sparse"}]},{"id":"perc","name":"Light Percussion","role":"pulse/rhythm","register":{"low":60,"high":72},"instrument_hint":"timpani, triangle, suspended cymbal","section_jobs":[{"section_id":"idea_a","intent":"triangle accent, sparse","density":"sparse"},{"section_id":"idea_b","intent":"timpani roll at phrase end","density":"sparse"},{"section_id":"argument","intent":"punctuate climax, cymbal swell","density":"medium"},{"section_id":"listening","intent":"very sparse, maybe triangle","density":"sparse"},{"section_id":"coexistence","intent":"gentle pulse, soft cymbal","density":"sparse"}]}],"motif_strategy":"A: angular ascending minor 9th leap then descending chromatic tail, rhythm [dotted-8th, 16th, 8th]; B: stepwise cantabile phrase with appoggiatura, rhythm [quarter, half, quarter]; argument fragments, reversal and overlap; coexistence interleaves both.","harmony_strategy":"Modal E minor with occasional F#/C# alterations, avoid functional cadences; sections use E aeolian, A lydian in B, chromatic side-slipping in argument, pedal E in listening, combined pandiatonic in coexistence.","groove_strategy":"4/4 at 120 bpm; pulse mainly in cello/bass, light percussion accents; argument uses syncopated offbeat accents and hemiola; listening nearly no pulse; coexistence has gentle 8th-note lilt."}

EXPERIMENTAL MUSIC SPEC SCHEMA:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://auto-studio.local/q0/experimental-music-spec.schema.json",
  "title": "ExperimentalMusicSpec",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "tempo_map", "key_map", "sections", "tracks"],
  "properties": {
    "title": {"type": "string", "minLength": 1, "maxLength": 120},
    "tempo_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/tempo_change"}},
    "key_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/key_change"}},
    "sections": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/section"}},
    "tracks": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "#/$defs/track"}}
  },
  "$defs": {
    "time_signature": {
      "type": "object", "additionalProperties": false,
      "required": ["numerator", "denominator"],
      "properties": {
        "numerator": {"type": "integer", "minimum": 1, "maximum": 32},
        "denominator": {"enum": [1, 2, 4, 8, 16, 32]}
      }
    },
    "tempo_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "bpm", "time_signature"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "bpm": {"type": "number", "minimum": 30, "maximum": 300},
        "time_signature": {"$ref": "#/$defs/time_signature"}
      }
    },
    "key_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "tonic", "mode"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "tonic": {"type": "string", "minLength": 1, "maxLength": 8},
        "mode": {"type": "string", "minLength": 1, "maxLength": 32}
      }
    },
    "section": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "label", "start_bar", "length_bars", "intent"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "label": {"type": "string", "minLength": 1, "maxLength": 80},
        "start_bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "length_bars": {"type": "integer", "minimum": 1, "maximum": 128},
        "intent": {"type": "string", "minLength": 1, "maxLength": 240}
      }
    },
    "register": {
      "type": "object", "additionalProperties": false,
      "required": ["low", "high"],
      "properties": {
        "low": {"type": "integer", "minimum": 0, "maximum": 127},
        "high": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "note": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "duration", "pitch", "velocity"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "duration": {"type": "number", "exclusiveMinimum": 0},
        "pitch": {"type": "integer", "minimum": 0, "maximum": 127},
        "velocity": {"type": "integer", "minimum": 1, "maximum": 127}
      }
    },
    "cc": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "controller", "value"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "controller": {"type": "integer", "minimum": 0, "maximum": 127},
        "value": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "region": {
      "type": "object", "additionalProperties": false,
      "required": ["section_id", "notes", "cc"],
      "properties": {
        "section_id": {"type": "string", "minLength": 1, "maxLength": 48},
        "notes": {"type": "array", "maxItems": 2048, "items": {"$ref": "#/$defs/note"}},
        "cc": {"type": "array", "maxItems": 1024, "items": {"$ref": "#/$defs/cc"}}
      }
    },
    "track": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "name", "role", "register", "instrument_hint", "regions"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "name": {"type": "string", "minLength": 1, "maxLength": 80},
        "role": {"type": "string", "minLength": 1, "maxLength": 80},
        "register": {"$ref": "#/$defs/register"},
        "instrument_hint": {"type": "string", "minLength": 1, "maxLength": 120},
        "regions": {"type": "array", "maxItems": 48, "items": {"$ref": "#/$defs/region"}}
      }
    }
  }
}
